//! Read-path behavior: config, state and schedule reads, and their exit codes.
//!
//! These tests are hermetic — every one runs against a fixture config/state
//! tree under `XPST_CONFIG_DIR`, never against the developer's real `~/.xpst`.
//! The config goldens are generated by the Python engine
//! (`xtask/scripts/generate_config_goldens.py`), so the assertion here is a
//! real differential check: the Rust read path must reproduce Python's
//! `xpst config show` output byte for byte, including masking decisions.

use std::ffi::OsString;
use std::path::PathBuf;
use std::sync::{Mutex, MutexGuard};

use xpst_cli::run_with_io;

const CONFIG_YAML: &str = include_str!("fixtures/config-sample.yaml");
const CONFIG_MASKED: &str = include_str!("fixtures/config-sample.masked.json");
const CONFIG_RAW: &str = include_str!("fixtures/config-sample.raw.json");

/// Serializes tests that mutate `XPST_CONFIG_DIR`: it is process-global state.
static ENV_LOCK: Mutex<()> = Mutex::new(());

struct Fixture {
    /// Root of this test's temp tree. The default profile lives in `profile/`,
    /// so a config written anywhere else is provably *not* the default one.
    dir: PathBuf,
    profile: PathBuf,
    _guard: MutexGuard<'static, ()>,
}

impl Fixture {
    fn new(name: &str) -> Self {
        // The lock is held for the lifetime of the fixture so no other test
        // can observe a different XPST_CONFIG_DIR halfway through.
        let guard = ENV_LOCK.lock().unwrap_or_else(|poison| poison.into_inner());
        let dir = std::env::temp_dir().join(format!(
            "xpst-rust-p0-{name}-{}-{}",
            std::process::id(),
            unique_suffix()
        ));
        let profile = dir.join("profile");
        std::fs::create_dir_all(&profile).expect("create fixture dir");
        std::env::set_var("XPST_CONFIG_DIR", &profile);
        Self {
            dir,
            profile,
            _guard: guard,
        }
    }

    /// Write into the default profile (`$XPST_CONFIG_DIR`).
    fn write(&self, name: &str, contents: &str) {
        std::fs::write(self.profile.join(name), contents).expect("write fixture file");
    }

    /// Write a file OUTSIDE the default profile and return its path as text —
    /// what a caller passes to `--file`/`--config`.
    fn write_external(&self, name: &str, contents: &str) -> String {
        let path = self.dir.join(name);
        std::fs::write(&path, contents).expect("write external fixture file");
        path.display().to_string()
    }

    /// A path outside the profile that deliberately does not exist.
    fn missing_external(&self, name: &str) -> String {
        self.dir.join(name).display().to_string()
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        std::env::remove_var("XPST_CONFIG_DIR");
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

fn unique_suffix() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0)
}

fn run(args: &[&str], stdout_is_tty: bool) -> (i32, String, String) {
    let mut argv: Vec<OsString> = vec![OsString::from("xpst")];
    argv.extend(args.iter().map(OsString::from));
    let mut out: Vec<u8> = Vec::new();
    let mut err: Vec<u8> = Vec::new();
    let code = run_with_io(argv, &mut out, &mut err, stdout_is_tty);
    (
        code,
        String::from_utf8_lossy(&out).into_owned(),
        String::from_utf8_lossy(&err).into_owned(),
    )
}

#[test]
fn config_show_reproduces_the_python_output_byte_for_byte() {
    let fixture = Fixture::new("show-masked");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "show"], false);
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(
        out, CONFIG_MASKED,
        "masked output must match the Python engine"
    );
}

#[test]
fn config_show_raw_reproduces_the_python_output() {
    let fixture = Fixture::new("show-raw");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "show", "--raw"], false);
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out, CONFIG_RAW, "raw output must match the Python engine");
}

#[test]
fn raw_output_is_the_only_way_a_secret_reaches_stdout() {
    let fixture = Fixture::new("masking");
    fixture.write("config.yaml", CONFIG_YAML);

    let (_, masked, _) = run(&["config", "show"], false);
    assert!(
        !masked.contains("/fixture/.xpst/credentials/youtube_token.json"),
        "masked output leaked a credential path: {masked}"
    );
    let (_, raw, _) = run(&["config", "show", "--raw"], false);
    assert!(
        raw.contains("/fixture/.xpst/credentials/youtube_token.json"),
        "--raw must show the unmodified value"
    );
}

#[test]
fn config_show_human_output_is_yaml_on_a_tty() {
    let fixture = Fixture::new("show-yaml");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "show"], true);
    assert_eq!(code, 0, "stderr: {err}");
    assert!(out.starts_with("version: 4"), "expected YAML, got: {out}");
    assert!(
        !out.trim_start().starts_with('{'),
        "a TTY gets YAML, not JSON"
    );
    // Masking still applies to the human surface.
    assert!(!out.contains("youtube_token.json"));
}

#[test]
fn missing_config_exits_2_with_the_documented_json_error() {
    let _fixture = Fixture::new("missing-config");

    let (code, out, _err) = run(&["config", "show"], false);
    assert_eq!(code, 2, "config errors are exit code 2");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON error");
    assert_eq!(payload["ok"], false);
    assert_eq!(payload["error"]["code"], "CONFIG_FILE_NOT_FOUND");
    assert!(payload["error"]["path"].as_str().is_some());
    assert!(payload["error"]["hint"]
        .as_str()
        .unwrap_or("")
        .contains("wizard"));
}

#[test]
fn invalid_yaml_exits_2_and_names_the_file() {
    let fixture = Fixture::new("invalid-yaml");
    fixture.write("config.yaml", "accounts: [\n");

    let (code, out, _err) = run(&["config", "show"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON error");
    assert_eq!(payload["error"]["code"], "INVALID_YAML");
    assert!(payload["error"]["message"]
        .as_str()
        .unwrap_or("")
        .contains("Invalid YAML in"));
}

#[test]
fn config_validate_reports_checks_and_exits_0_for_a_good_config() {
    let fixture = Fixture::new("validate-ok");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "validate"], false);
    assert_eq!(code, 0, "stderr: {err}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["valid"], true);
    assert!(payload["checks"].as_array().expect("checks").len() >= 4);
}

#[test]
fn config_validate_flags_an_unrecognised_document() {
    let fixture = Fixture::new("validate-unknown");
    fixture.write("config.yaml", "totally_unrelated: 1\n");

    let (code, out, _err) = run(&["config", "validate"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["valid"], false);
}

#[test]
fn doctor_reads_live_state_and_reports_an_absent_schedule_as_healthy() {
    let fixture = Fixture::new("doctor-ok");
    fixture.write("config.yaml", CONFIG_YAML);
    fixture.write(
        "state.json",
        r#"{"version": 2, "posted_videos": {"a": {"posted_to": {"x": {"id": "1", "deleted": false}}}}, "content_hashes": {"h": "a"}}"#,
    );
    // No schedule.json: the paused install looks exactly like this.

    let (code, out, err) = run(&["doctor"], false);
    assert_eq!(code, 0, "stderr: {err}\nstdout: {out}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["ok"], true);
    assert_eq!(payload["engine"]["name"], "rust");
    assert_eq!(payload["engine"]["live_checks"], false);
    assert_eq!(payload["state"]["version"], 2);
    assert_eq!(payload["state"]["videos"], 1);
    assert_eq!(payload["schedule"]["present"], false);
    assert_eq!(payload["schedule"]["entries"], 0);
}

#[test]
fn doctor_fails_on_an_unreadable_config() {
    let _fixture = Fixture::new("doctor-missing");

    let (code, out, _err) = run(&["doctor"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["ok"], false);
    assert_eq!(payload["config"]["readable"], false);
}

#[test]
fn doctor_refuses_a_future_state_schema() {
    let fixture = Fixture::new("doctor-future-state");
    fixture.write("config.yaml", CONFIG_YAML);
    fixture.write("state.json", r#"{"version": 99, "posted_videos": {}}"#);

    let (code, out, _err) = run(&["doctor"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["ok"], false);
    assert!(payload["state"]["error"]
        .as_str()
        .unwrap_or("")
        .contains("Unsupported state schema version 99"));
}

#[test]
fn version_flag_matches_the_click_output_shape() {
    let (code, out, _err) = run(&["--version"], false);
    assert_eq!(code, 0);
    assert!(
        out.starts_with("xPST, version "),
        "expected Click's version shape, got: {out}"
    );
}

// ---------------------------------------------------------------------------
// `--file` — the flag that names the config a caller is asking about.
//
// The failure this pins was a silent wrong-file read: `config show --file X`
// printed the default profile's document with exit 0. Every assertion below
// therefore compares against a document that exists ONLY outside the default
// profile, so a fallback cannot pass by accident.
// ---------------------------------------------------------------------------

#[test]
fn config_show_file_reads_the_named_file_not_the_default_profile() {
    let fixture = Fixture::new("show-file");
    fixture.write("config.yaml", "version: 4\ndefault_only: yes-here\n");
    let other = fixture.write_external("other.yaml", "version: 4\nzzz_only_here: hello\n");

    let (code, out, err) = run(&["config", "show", "--file", &other], false);
    assert_eq!(code, 0, "stderr: {err}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(
        payload["zzz_only_here"], "hello",
        "--file must select the named document, got: {out}"
    );
    assert!(
        payload.get("default_only").is_none(),
        "--file fell back to the default profile: {out}"
    );
}

#[test]
fn config_show_file_human_output_is_the_named_file() {
    let fixture = Fixture::new("show-file-yaml");
    fixture.write("config.yaml", "version: 4\ndefault_only: yes-here\n");
    let other = fixture.write_external("other.yaml", "version: 4\nzzz_only_here: hello\n");

    let (code, out, err) = run(&["config", "show", "--file", &other], true);
    assert_eq!(code, 0, "stderr: {err}");
    assert!(out.contains("zzz_only_here"), "TTY output: {out}");
    assert!(!out.contains("default_only"), "TTY output: {out}");
}

#[test]
fn config_show_file_missing_path_is_the_documented_not_found_error() {
    let fixture = Fixture::new("show-file-missing");
    fixture.write("config.yaml", CONFIG_YAML);
    let missing = fixture.missing_external("absent.yaml");

    let (code, out, err) = run(&["config", "show", "--file", &missing], false);
    assert_eq!(
        code, 2,
        "a missing --file is the documented config error (exit 2), not success. \
         stdout: {out} stderr: {err}"
    );
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON error");
    assert_eq!(payload["ok"], false);
    assert_eq!(payload["error"]["code"], "CONFIG_FILE_NOT_FOUND");
    assert_eq!(
        payload["error"]["path"], missing,
        "the payload must name the file the caller asked about"
    );
    assert!(payload["error"]["message"]
        .as_str()
        .unwrap_or("")
        .contains(&missing));
    assert!(payload["error"]["hint"]
        .as_str()
        .unwrap_or("")
        .contains("wizard"));
}

#[test]
fn config_show_file_missing_path_is_reported_in_human_mode_too() {
    let fixture = Fixture::new("show-file-missing-human");
    fixture.write("config.yaml", CONFIG_YAML);
    let missing = fixture.missing_external("absent.yaml");

    let (code, out, err) = run(&["config", "show", "--file", &missing], true);
    assert_eq!(code, 2, "stdout: {out}");
    assert!(
        err.contains("Config file not found:") && err.contains(&missing),
        "stderr must name the missing file, got: {err}"
    );
    assert!(
        !out.contains("version: 4"),
        "a failed read must not print the default profile: {out}"
    );
}

#[test]
fn config_show_file_wins_over_the_root_config_flag() {
    let fixture = Fixture::new("show-file-precedence");
    fixture.write("config.yaml", "version: 4\ndefault_only: yes-here\n");
    let root_config = fixture.write_external("root.yaml", "version: 4\nfrom_root: root\n");
    let leaf_file = fixture.write_external("leaf.yaml", "version: 4\nfrom_leaf: leaf\n");

    let (code, out, err) = run(
        &[
            "--config",
            &root_config,
            "config",
            "show",
            "--file",
            &leaf_file,
        ],
        false,
    );
    assert_eq!(code, 0, "stderr: {err}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(
        payload["from_leaf"], "leaf",
        "the leaf --file must outrank the root --config, got: {out}"
    );
    assert!(payload.get("from_root").is_none(), "{out}");
}

#[test]
fn config_show_json_flag_is_honoured_on_a_tty() {
    // `--json` used to be read by Click's parameter name, so the flag was
    // accepted and then ignored: a TTY got YAML. A caller scripting a TTY
    // session must still get JSON.
    let fixture = Fixture::new("show-json-flag");
    fixture.write("config.yaml", "version: 4\nonly_here: hello\n");

    let (code, out, err) = run(&["config", "show", "--json"], true);
    assert_eq!(code, 0, "stderr: {err}");
    let payload: serde_json::Value = serde_json::from_str(out.trim())
        .unwrap_or_else(|e| panic!("--json on a TTY printed {out:?}: {e}"));
    assert_eq!(payload["only_here"], "hello");
}

#[test]
fn config_validate_honours_file() {
    let fixture = Fixture::new("validate-file");
    fixture.write("config.yaml", CONFIG_YAML);
    let other = fixture.write_external("other.yaml", "version: 4\nunrelated_section: 1\n");
    // `version: 4` alone is enough to look like an xPST config, so this case
    // only proves the file was read. The next one drops the version key too.
    let (code, out, _err) = run(&["config", "validate", "--file", &other], false);
    assert_eq!(
        code, 0,
        "a readable document with a version must validate: {out}"
    );

    let unrelated = fixture.write_external("unrelated.yaml", "only_this: 1\n");
    let (code, out, err) = run(&["config", "validate", "--file", &unrelated], false);
    assert_eq!(
        code, 2,
        "the named document is not an xPST config, so it must fail: {out} {err}"
    );
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["valid"], false);

    // The mirror case: a valid document outside the profile must pass, and the
    // check that reports the loaded file must name it.
    let good = fixture.write_external("good.yaml", CONFIG_YAML);
    let (code, out, err) = run(&["config", "validate", "--file", &good], false);
    assert_eq!(code, 0, "stderr: {err}\nstdout: {out}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["valid"], true);
    let loaded = payload["checks"]
        .as_array()
        .expect("checks")
        .iter()
        .find(|check| check["name"] == "Config file loaded")
        .expect("a `Config file loaded` check");
    assert_eq!(loaded["ok"], true);
    assert!(
        loaded["detail"].as_str().unwrap_or("").contains(&good),
        "the load check must name the file it read: {loaded}"
    );
}

#[test]
fn config_leaves_that_document_file_either_honour_it_or_refuse() {
    // Every `config` leaf whose Click definition has `--file`. `show` and
    // `validate` read it (tests above); the rest are still P0 stubs, and the
    // one thing they must not do is accept the flag and act on another file —
    // they refuse with the documented NOT_IMPLEMENTED payload.
    let fixture = Fixture::new("config-file-leaves");
    let other = fixture.write_external("other.yaml", "version: 4\nzzz_only_here: hello\n");

    let leaves: [&[&str]; 3] = [
        &["config", "set", "a.b", "1"],
        &["config", "export", "out.yaml"],
        &["config", "fix"],
    ];
    for leaf in leaves {
        let mut args: Vec<&str> = leaf.to_vec();
        args.push("--file");
        args.push(&other);
        let (code, out, err) = run(&args, false);
        assert_eq!(
            code,
            1,
            "`{}` must exit 1 (not implemented), not act on a file: {out} {err}",
            leaf.join(" ")
        );
        let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
        assert_eq!(
            payload["error"]["code"],
            "NOT_IMPLEMENTED",
            "`{}` must say it is unimplemented: {out}",
            leaf.join(" ")
        );
    }

    // The manifest is the authority for "documents --file": if a fourth leaf
    // gains the flag in the Python tree, this count is what fails.
    let leaves_with_file = xpst_cli::parity::manifest()
        .commands
        .iter()
        .filter(|command| command.path.first().map(String::as_str) == Some("config"))
        .filter(|command| {
            command
                .params
                .iter()
                .any(|param| param.long_opts().contains(&"--file"))
        })
        .map(|command| command.path.join(" "))
        .collect::<Vec<_>>();
    assert_eq!(
        leaves_with_file,
        vec![
            "config export",
            "config fix",
            "config set",
            "config show",
            "config validate"
        ],
        "the set of config leaves documenting --file changed"
    );
}

#[test]
fn config_validate_file_missing_path_fails_the_load_check() {
    let fixture = Fixture::new("validate-file-missing");
    fixture.write("config.yaml", CONFIG_YAML);
    let missing = fixture.missing_external("absent.yaml");

    let (code, out, err) = run(&["config", "validate", "--file", &missing], false);
    assert_eq!(code, 2, "stdout: {out} stderr: {err}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["valid"], false);
    let loaded = &payload["checks"][0];
    assert_eq!(loaded["name"], "Config file loaded");
    assert_eq!(loaded["ok"], false);
    assert!(
        loaded["detail"].as_str().unwrap_or("").contains(&missing),
        "the failed check must name the missing file: {loaded}"
    );
}
